import{app,BrowserWindow,WebContentsView}from'electron';import{mkdtemp,writeFile}from'node:fs/promises';import{join,resolve}from'node:path';import assert from'node:assert/strict';import{attachPlaywrightView}from'../../packages/browser/src/playwright-view.js';import{READ_UNIVERSAL_FORM}from'../../packages/browser/src/universal-read.js';import{UniversalFormSession}from'../../packages/browser/src/universal-form.js';import{profile,html}from'./moka-form.js';
const dir=await mkdtemp(resolve('.backups/moka-semantic-'));app.setPath('userData',dir);await app.whenReady();const win=new BrowserWindow({show:false}),view=new WebContentsView({webPreferences:{partition:'moka-semantic-fixture',sandbox:true,contextIsolation:true,nodeIntegration:false,backgroundThrottling:false}});win.contentView.addChildView(view);view.setBounds({x:0,y:0,width:1100,height:800});

try{await view.webContents.loadURL('data:text/html;charset=utf-8,'+encodeURIComponent(html));const attached=await attachPlaywrightView(view.webContents),page=attached.page;const before=await page.locator('input,textarea').evaluateAll(nodes=>nodes.map((e:any)=>e.value));const read:any=await page.evaluate(READ_UNIVERSAL_FORM);const after=await page.locator('input,textarea').evaluateAll(nodes=>nodes.map((e:any)=>e.value));assert.deepEqual(after,before);assert.equal(await page.evaluate('window.events'),0);
 assert.equal(read.fields.find((f:any)=>f.label==='所在地 / Location *').value,'');assert.ok(read.fields.filter((f:any)=>f.label==='就读时间 / Education period *').length===8);
 const schools=read.fields.filter((f:any)=>f.label==='学校名称 / School *');assert.equal(schools.length,2);assert.notEqual(schools[0].group,schools[1].group);assert.ok(schools.every((f:any)=>f.readOnlyWidget&&f.value.includes(' / Fictional University')));
 const company=read.fields.find((f:any)=>f.label==='公司名称 / Company'),role=read.fields.find((f:any)=>f.label==='职位名称 / Job title'),description=read.fields.find((f:any)=>f.label==='工作职责 / Responsibilities');assert.equal(role.group,company.group);assert.equal(description.group,company.group);assert.equal(role.section,'实习经历');
 const session=new UniversalFormSession(page,profile,async()=>profile,()=>1,new AbortController().signal);const obs=await session.inspect();assert.equal(obs.fields.length,2);assert.ok(obs.manualFields.some(f=>f.label==='GPA/CGPA *'));const outcome=await session.fillGroup(obs.observation,obs.fields.map(f=>({target:f.ref,fact:f.candidates[0]!})));assert.equal(outcome.verified,2);assert.equal(outcome.failures.length,0);assert.equal(await page.locator('#role').inputValue(),'算法实习生');assert.equal(await page.locator('#description').inputValue(),profile.career!.internships[0]!.description);assert.equal(await page.locator('#visa').inputValue(),'');assert.equal(await page.locator('#city').inputValue(),'');const final=await session.verify();assert.equal(final.missingRecords.length,0);assert.equal(await page.evaluate('window.submits'),0);
 session.close();await page.locator('.record-fixture').last().evaluate(e=>e.remove());const add=new UniversalFormSession(page,profile,async()=>profile,()=>1,new AbortController().signal);const next=await add.inspect();assert.equal(next.actions.length,1);assert.equal(next.actions[0]!.label,'添加教育经历');await add.act({observation:next.observation,action:'add',target:next.actions[0]!.ref});assert.equal(await page.locator('.record-fixture').count(),2);add.close();
 await attached.close();const result={mokaSmoke:true,ok:true,verifiedTargets:2,separateEducations:2,readOnlyNoMutations:true,missingDataNotGuessed:true,semanticAdd:true,paidRequests:0};await writeFile(join(dir,'report.json'),JSON.stringify(result));console.log(JSON.stringify(result));view.webContents.close();win.destroy();app.exit(0);
}catch(e){console.error(e);win.destroy();app.exit(1);}
